namespace Linx.Internet.Application.Framework
{
    public class MyRazorView : IView
    {
        private string _viewPath;
        private string _physicalpath;
        private IView _viewOriginal;
        private NameValueCollection _queryStrings;


        public MyRazorView(string viewPath, ControllerContext controllerContext, IView viewOriginal)
        {
            _viewPath = viewPath;
            _physicalpath = controllerContext.HttpContext.Server.MapPath(viewPath);
            _queryStrings = controllerContext.HttpContext.Request.QueryString;
            _viewOriginal = viewOriginal;
        }

        #region IView Members

        public void Render(ViewContext viewContext, System.IO.TextWriter writer)
        {
            // redenriza o comentario de referencia
            if (_queryStrings["refview"] == "on")
            {
                writer.WriteLine("<!-- INI: '{0}' -->", _viewPath);
                writer.WriteLine();
            }

            // adiciona conteudo do arquivo xx.cshtml_header se existir
            if (FileExists("header"))
            {
                writer.WriteLine(ContenFile("header"));
            }

            // conteudo da view original
            _viewOriginal.Render(viewContext, writer);

            // adiciona conteudo do arquivo xx.cshtml_footer se existir
            if (FileExists("footer"))
            {
                writer.WriteLine(ContenFile("footer"));
            }

            // redenriza o comentario de referencia
            if (_queryStrings["refview"] == "on")
            {
                writer.WriteLine();
                writer.WriteLine("<!-- FIM: '{0}' -->", _viewPath);
            }
        }

        #endregion

        private bool FileExists(string typeFile)
        {
            string path = string.Concat(_physicalpath, "_", typeFile);

            return File.Exists(path);
        }

        private string ContenFile(string typeFile)
        {
            string path = string.Concat(_physicalpath, "_", typeFile);

            return File.ReadAllText(path);
